from app.rules import Features, Rules

r = Rules("config/rules.yaml")


def F(**kw):
    base = dict(freshness="fresh", count_5m=1, amount_ratio=1.0, new_device=False,
                blocked=False, amount_minor=1000)
    return Features(**{**base, **kw})


def test_blocked_declines():        assert r.evaluate(F(blocked=True)).decision == "DECLINE"
def test_velocity_declines():       assert r.evaluate(F(count_5m=11)).decision == "DECLINE"
def test_velocity_boundary_ok():    assert r.evaluate(F(count_5m=10)).decision == "APPROVE"
def test_stale_skips_velocity():    assert r.evaluate(F(freshness="stale", count_5m=11)).decision == "APPROVE"
def test_large_new_device():        assert r.evaluate(F(amount_ratio=6.5, new_device=True)).decision == "STEP_UP"
def test_large_known_device_ok():   assert r.evaluate(F(amount_ratio=6.5, new_device=False)).decision == "APPROVE"
def test_new_card_big_amount():
    assert r.evaluate(F(freshness="missing", amount_ratio=None, amount_minor=30000)).decision == "STEP_UP"
def test_fallback_thresholds():
    assert r.fallback(500).decision == "APPROVE" and r.fallback(50000).decision == "STEP_UP"
